// PuzzleServiceHandler is an implementation of the meurpg.play.v1.PuzzleService service.
type PuzzleServiceHandler interface {
	// CreatePuzzle makes a puzzle in the campaign. Master only.
	//
	// The server checks the config and the answer, generates the start of the lights
	// and of the pillars from the seed (a start that is already solved is never given:
	// it is drawn again from the same seed), and works out the fewest moves. A lock's
	// start is the one in the request. The "Ao resolver" target must be a door, point
	// or clue of this campaign.
	//
	// Errors: `permission_denied` for a player; `invalid_argument` (PuzzleInvalid).
	//
	// Safe to retry when the request carries an idempotency_key: a second call with the same key and
	// the same request returns what the first one made and makes nothing; the same key with another
	// request is `invalid_argument`. Without a key the call is not deduplicated.
	CreatePuzzle(context.Context, *connect.Request[v1.CreatePuzzleRequest]) (*connect.Response[v1.CreatePuzzleResponse], error)
	// UpdatePuzzle replaces everything the master wrote about a puzzle (the same fields
	// as CreatePuzzle), as long as the puzzle was never shown in a session. Master only.
	//
	// Errors: `permission_denied`; `invalid_argument`; `failed_precondition`
	// (ALREADY_SHOWN).
	UpdatePuzzle(context.Context, *connect.Request[v1.UpdatePuzzleRequest]) (*connect.Response[v1.UpdatePuzzleResponse], error)
	// PreviewPuzzleStart draws a start for the form, with the fewest moves from it,
	// and stores nothing: "Gerar outro começo" in the create form. The same seed and
	// config always give the same start, so sending the seed back to CreatePuzzle
	// creates exactly that start. Master only. Lights and pillars only.
	//
	// Errors: `permission_denied`; `invalid_argument`; `failed_precondition`
	// (NO_GENERATED_START for a lock).
	PreviewPuzzleStart(context.Context, *connect.Request[v1.PreviewPuzzleStartRequest]) (*connect.Response[v1.PreviewPuzzleStartResponse], error)
	// ListPuzzles lists the campaign's puzzles, newest first, with their answers. Master
	// only. Archived ones only when asked.
	ListPuzzles(context.Context, *connect.Request[v1.ListPuzzlesRequest]) (*connect.Response[v1.ListPuzzlesResponse], error)
	// GetPuzzle reads one puzzle, archived or not. Master only.
	GetPuzzle(context.Context, *connect.Request[v1.GetPuzzleRequest]) (*connect.Response[v1.GetPuzzleResponse], error)
	// ArchivePuzzle takes a puzzle out of the lists and from the session's menu; what
	// happened in past sessions stays. Archiving an archived puzzle changes nothing.
	// Master only.
	ArchivePuzzle(context.Context, *connect.Request[v1.ArchivePuzzleRequest]) (*connect.Response[v1.ArchivePuzzleResponse], error)
	// UnarchivePuzzle brings an archived puzzle back. Master only.
	UnarchivePuzzle(context.Context, *connect.Request[v1.UnarchivePuzzleRequest]) (*connect.Response[v1.UnarchivePuzzleResponse], error)
	// ListSessionPuzzles lists the campaign's puzzles that are not archived, each with
	// where it stands in the open session: the master's menu. Master only.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION).
	ListSessionPuzzles(context.Context, *connect.Request[v1.ListSessionPuzzlesRequest]) (*connect.Response[v1.ListSessionPuzzlesResponse], error)
	// ShowPuzzle shows the puzzle to every player of the open session ("Mostrar aos
	// jogadores"): the run is made at the puzzle's start. Showing a shown one changes
	// nothing; showing a closed one opens it again at its start; showing a solved one
	// changes nothing. Master only.
	//
	// Writes the session event `puzzle_shown` and sends `puzzle_changed` to everyone.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION, ARCHIVED).
	ShowPuzzle(context.Context, *connect.Request[v1.ShowPuzzleRequest]) (*connect.Response[v1.ShowPuzzleResponse], error)
	// ResetPuzzle ("Recomeçar") puts the run back at the same start it had, for every
	// player, solved or not: the state, the last move and the solved mark go; the hints
	// released and the history of moves stay. Master only.
	//
	// Writes `puzzle_reset`.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION, STALE_REVISION, NOT_SHOWN).
	ResetPuzzle(context.Context, *connect.Request[v1.ResetPuzzleRequest]) (*connect.Response[v1.ResetPuzzleResponse], error)
	// ReseedPuzzle ("Gerar outro começo") draws a new seed and a new start for the run,
	// never already solved, and puts the run at it, as ResetPuzzle does. Lights and
	// pillars only. The puzzle's own start is not changed: Recomeçar of a later session
	// starts from it. Master only. Allowed before and after the puzzle is shown (before,
	// the run is prepared at the new start and the players see nothing until ShowPuzzle).
	//
	// Writes `puzzle_reset`.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION, STALE_REVISION, NO_GENERATED_START).
	ReseedPuzzle(context.Context, *connect.Request[v1.ReseedPuzzleRequest]) (*connect.Response[v1.ReseedPuzzleResponse], error)
	// ClosePuzzle ("Fechar") hides the puzzle from the players. Closing a closed one
	// changes nothing. Master only.
	//
	// Writes `puzzle_closed`.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION, NOT_SHOWN).
	ClosePuzzle(context.Context, *connect.Request[v1.ClosePuzzleRequest]) (*connect.Response[v1.ClosePuzzleResponse], error)
	// ReleaseNextPuzzleHint ("Mostrar a próxima dica") releases the next hint to the
	// players. Master only.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION, STALE_REVISION, NOT_SHOWN, NO_MORE_HINTS).
	ReleaseNextPuzzleHint(context.Context, *connect.Request[v1.ReleaseNextPuzzleHintRequest]) (*connect.Response[v1.ReleaseNextPuzzleHintResponse], error)
	// PreviewPuzzleCipher ciphers a message for the form, as the players will read it
	// ("Como os jogadores a veem"), and stores nothing. Master only.
	//
	// Errors: `permission_denied`; `invalid_argument` (PuzzleInvalid CIPHER).
	PreviewPuzzleCipher(context.Context, *connect.Request[v1.PreviewPuzzleCipherRequest]) (*connect.Response[v1.PreviewPuzzleCipherResponse], error)
	// PlayPuzzleSequence ("Tocar a sequência") plays the sequence for the players. Master
	// only. The server reveals it step by step, one every SequencePlayback.step_ms, never
	// a step before its time: each app reads the run again at every puzzle_changed and
	// when `next_in_ms` runs out. A play that runs when the master plays again starts over.
	// Counts one more play (SequencePlayback.plays) and does not touch the attempt's
	// progress or the counters of "Ao errar".
	//
	// Sends `puzzle_changed` now and at each step. Writes no session event.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION, STALE_REVISION, NOT_SHOWN, NOT_A_SEQUENCE,
	// SOLVED, STOPPED).
	PlayPuzzleSequence(context.Context, *connect.Request[v1.PlayPuzzleSequenceRequest]) (*connect.Response[v1.PlayPuzzleSequenceResponse], error)
	// GetMasterPuzzleRun is the master's live view of a puzzle of the open session: what
	// the players read, and the answer, the fewest moves left and the hints. Master only.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION).
	GetMasterPuzzleRun(context.Context, *connect.Request[v1.GetMasterPuzzleRunRequest]) (*connect.Response[v1.GetMasterPuzzleRunResponse], error)
	// ListShownPuzzles lists the puzzles the open session shows: shown, not closed,
	// solved or not. Any member may call it, and gets what a player gets.
	//
	// Errors: `failed_precondition` (NO_OPEN_SESSION).
	ListShownPuzzles(context.Context, *connect.Request[v1.ListShownPuzzlesRequest]) (*connect.Response[v1.ListShownPuzzlesResponse], error)
	// GetPuzzleRun reads a shown puzzle as a player reads it (RN-10, RN-27). Any member
	// may call it. A puzzle that does not exist, is not shown or was closed answers
	// `not_found`.
	//
	// Errors: `not_found`; `failed_precondition` (NO_OPEN_SESSION).
	GetPuzzleRun(context.Context, *connect.Request[v1.GetPuzzleRunRequest]) (*connect.Response[v1.GetPuzzleRunResponse], error)
	// TryPuzzleHint ("Tentar uma dica · Investigação") rolls the puzzle's skill check for
	// the next hint, as the caller's living character. Players only (RN-18: the app
	// rolls the d20, or the player types the face of a real one; the campaign may force
	// one way). A pass gives that player, and only them, the next hint they do not read
	// yet (the first one the master did not release, or after the ones they won). A
	// fail gives nothing, and the same player cannot try again for the same hint until the
	// master releases it. (Another player passing does not free it: a pass gives that
	// player their own hint.) The DC is never sent. The answer is the run
	// as the player reads it now, and the roll.
	//
	// Each try is kept (puzzle_hint_tries) and counts one revision of the run; it writes
	// no session event and sends `puzzle_changed`. A try with an idempotency_key already
	// used is not rolled again.
	//
	// Errors: `permission_denied` for the master; `not_found` (unknown or unshown puzzle);
	// `invalid_argument`; `failed_precondition` (NO_OPEN_SESSION, SOLVED, STOPPED,
	// NO_CHARACTER, NO_HINT_CHECK, NO_MORE_HINTS, HINT_ALREADY_TRIED, WRONG_DICE_MODE,
	// NO_SKILL).
	TryPuzzleHint(context.Context, *connect.Request[v1.TryPuzzleHintRequest]) (*connect.Response[v1.TryPuzzleHintResponse], error)
	// MakePuzzleMove makes one move as the caller's living character. Players only.
	//
	// The server applies the move to the latest state, so two players moving at once
	// both count. When the move solves the puzzle, in the same transaction the run is
	// frozen, `puzzle_solved` is written and the master's "Ao resolver" action runs. A
	// move with an idempotency_key already used is not applied again: the answer is
	// the run as it is now (it may carry other players' moves made since, not the
	// first answer), with replayed = true.
	//
	// Writes the move in the puzzle's own history (not in the session's events, which
	// keep only the shown, solved, reset and closed of a puzzle) and sends
	// `puzzle_changed` to everyone.
	//
	// A riddle's or a cipher's answer and a sequence's bell are judged, not applied: a
	// wrong one changes nothing in the state (a wrong bell sends the attempt back to the
	// first step), is marked `wrong` in the history, and does what "Ao errar" says, all
	// in the transaction of the move: it spends the player's attempt, counts toward the
	// limits, and fires the trap point (once; the move's key makes a retry fire nothing).
	// The move that reaches a limit of moves stops the puzzle (unless it solves it). A time
	// limit stops it with no move at all: it is worked out from the clock, so the first
	// move after the time ran out is refused with STOPPED, and every read says `stopped`
	// from the moment it ran out.
	//
	// Errors: `not_found` (unknown or unshown puzzle); `permission_denied` for the master;
	// `invalid_argument` (PuzzleInvalid MOVE or KIND; a key that is not a UUID or was used
	// for another change carries no PuzzleInvalid detail); `failed_precondition` (NO_OPEN_SESSION,
	// SOLVED, STOPPED, NO_CHARACTER, NO_ATTEMPTS_LEFT, SEQUENCE_NOT_PLAYED, SEQUENCE_PLAYING).
	MakePuzzleMove(context.Context, *connect.Request[v1.MakePuzzleMoveRequest]) (*connect.Response[v1.MakePuzzleMoveResponse], error)
}

